#pragma once

#include <stdint.h>
#include <stdlib.h>
#include <wayland-client.h>

/*
 * Minimal client bindings for the exact protocol set generated by Ghostty's
 * pinned build: KDE blur, server-decoration, slide, and xdg-activation-v1.
 * Keeping this here gives the V translation the same wire requests without
 * requiring Zig's build-time wayland scanner.
 */

static const struct wl_interface witty_kde_blur_interface;
static const struct wl_interface witty_kde_decoration_interface;
static const struct wl_interface witty_kde_slide_interface;
static const struct wl_interface witty_xdg_activation_token_interface;

static const struct wl_interface *witty_blur_types[] = {
    &witty_kde_blur_interface,
    &wl_surface_interface,
    &wl_surface_interface,
    &wl_region_interface,
};
static const struct wl_message witty_kde_blur_manager_requests[] = {
    { "create", "no", witty_blur_types + 0 },
    { "unset", "o", witty_blur_types + 2 },
};
static const struct wl_interface witty_kde_blur_manager_interface = {
    "org_kde_kwin_blur_manager", 1,
    2, witty_kde_blur_manager_requests,
    0, NULL,
};
static const struct wl_message witty_kde_blur_requests[] = {
    { "commit", "", witty_blur_types + 0 },
    { "set_region", "?o", witty_blur_types + 3 },
    { "release", "", witty_blur_types + 0 },
};
static const struct wl_interface witty_kde_blur_interface = {
    "org_kde_kwin_blur", 1,
    3, witty_kde_blur_requests,
    0, NULL,
};

static const struct wl_interface *witty_decoration_types[] = {
    NULL,
    &witty_kde_decoration_interface,
    &wl_surface_interface,
};
static const struct wl_message witty_kde_decoration_manager_requests[] = {
    { "create", "no", witty_decoration_types + 1 },
};
static const struct wl_message witty_kde_decoration_manager_events[] = {
    { "default_mode", "u", witty_decoration_types + 0 },
};
static const struct wl_interface witty_kde_decoration_manager_interface = {
    "org_kde_kwin_server_decoration_manager", 1,
    1, witty_kde_decoration_manager_requests,
    1, witty_kde_decoration_manager_events,
};
static const struct wl_message witty_kde_decoration_requests[] = {
    { "release", "", witty_decoration_types + 0 },
    { "request_mode", "u", witty_decoration_types + 0 },
};
static const struct wl_message witty_kde_decoration_events[] = {
    { "mode", "u", witty_decoration_types + 0 },
};
static const struct wl_interface witty_kde_decoration_interface = {
    "org_kde_kwin_server_decoration", 1,
    2, witty_kde_decoration_requests,
    1, witty_kde_decoration_events,
};

static const struct wl_interface *witty_slide_types[] = {
    NULL,
    &witty_kde_slide_interface,
    &wl_surface_interface,
    &wl_surface_interface,
};
static const struct wl_message witty_kde_slide_manager_requests[] = {
    { "create", "no", witty_slide_types + 1 },
    { "unset", "o", witty_slide_types + 3 },
};
static const struct wl_interface witty_kde_slide_manager_interface = {
    "org_kde_kwin_slide_manager", 1,
    2, witty_kde_slide_manager_requests,
    0, NULL,
};
static const struct wl_message witty_kde_slide_requests[] = {
    { "commit", "", witty_slide_types + 0 },
    { "set_location", "u", witty_slide_types + 0 },
    { "set_offset", "i", witty_slide_types + 0 },
    { "release", "", witty_slide_types + 0 },
};
static const struct wl_interface witty_kde_slide_interface = {
    "org_kde_kwin_slide", 1,
    4, witty_kde_slide_requests,
    0, NULL,
};

static const struct wl_interface *witty_activation_types[] = {
    NULL,
    &witty_xdg_activation_token_interface,
    NULL,
    &wl_surface_interface,
    NULL,
    &wl_seat_interface,
    &wl_surface_interface,
};
static const struct wl_message witty_xdg_activation_requests[] = {
    { "destroy", "", witty_activation_types + 0 },
    { "get_activation_token", "n", witty_activation_types + 1 },
    { "activate", "so", witty_activation_types + 2 },
};
static const struct wl_interface witty_xdg_activation_interface = {
    "xdg_activation_v1", 1,
    3, witty_xdg_activation_requests,
    0, NULL,
};
static const struct wl_message witty_xdg_activation_token_requests[] = {
    { "set_serial", "uo", witty_activation_types + 4 },
    { "set_app_id", "s", witty_activation_types + 0 },
    { "set_surface", "o", witty_activation_types + 6 },
    { "commit", "", witty_activation_types + 0 },
    { "destroy", "", witty_activation_types + 0 },
};
static const struct wl_message witty_xdg_activation_token_events[] = {
    { "done", "s", witty_activation_types + 0 },
};
static const struct wl_interface witty_xdg_activation_token_interface = {
    "xdg_activation_token_v1", 1,
    5, witty_xdg_activation_token_requests,
    1, witty_xdg_activation_token_events,
};

enum witty_wayland_interface {
    WITTY_KDE_BLUR_MANAGER,
    WITTY_KDE_DECORATION_MANAGER,
    WITTY_KDE_SLIDE_MANAGER,
    WITTY_XDG_ACTIVATION,
};

static inline const struct wl_interface *
witty_wayland_interface_for_kind(uint32_t kind)
{
    switch (kind) {
    case WITTY_KDE_BLUR_MANAGER: return &witty_kde_blur_manager_interface;
    case WITTY_KDE_DECORATION_MANAGER: return &witty_kde_decoration_manager_interface;
    case WITTY_KDE_SLIDE_MANAGER: return &witty_kde_slide_manager_interface;
    case WITTY_XDG_ACTIVATION: return &witty_xdg_activation_interface;
    default: return NULL;
    }
}

static inline void *
witty_wayland_registry_bind(struct wl_registry *registry, uint32_t name,
                            uint32_t kind, uint32_t version)
{
    const struct wl_interface *interface = witty_wayland_interface_for_kind(kind);
    if (interface == NULL)
        return NULL;
    if (version > (uint32_t) interface->version)
        version = (uint32_t) interface->version;
    return wl_registry_bind(registry, name, interface, version);
}

typedef void (*witty_registry_global_fn)(void *, struct wl_registry *,
                                         uint32_t, const char *, uint32_t);
typedef void (*witty_registry_remove_fn)(void *, struct wl_registry *, uint32_t);

struct witty_registry_listener {
    struct wl_registry_listener listener;
};

static inline void *
witty_wayland_registry_add_listener(struct wl_registry *registry,
                                    witty_registry_global_fn global,
                                    witty_registry_remove_fn remove,
                                    void *data)
{
    struct witty_registry_listener *holder = calloc(1, sizeof(*holder));
    if (holder == NULL)
        return NULL;
    holder->listener.global = global;
    holder->listener.global_remove = remove;
    if (wl_registry_add_listener(registry, &holder->listener, data) < 0) {
        free(holder);
        return NULL;
    }
    return holder;
}

typedef void (*witty_decoration_mode_fn)(void *, void *, uint32_t);

struct witty_decoration_listener {
    witty_decoration_mode_fn default_mode;
};

static inline void *
witty_kde_decoration_add_listener(void *manager,
                                  witty_decoration_mode_fn callback,
                                  void *data)
{
    struct witty_decoration_listener *listener = calloc(1, sizeof(*listener));
    if (listener == NULL)
        return NULL;
    listener->default_mode = callback;
    if (wl_proxy_add_listener((struct wl_proxy *) manager,
                              (void (**)(void)) listener, data) < 0) {
        free(listener);
        return NULL;
    }
    return listener;
}

typedef void (*witty_activation_done_fn)(void *, void *, const char *);

struct witty_activation_listener {
    witty_activation_done_fn done;
};

static inline void *
witty_xdg_activation_token_add_listener(void *token,
                                        witty_activation_done_fn callback,
                                        void *data)
{
    struct witty_activation_listener *listener = calloc(1, sizeof(*listener));
    if (listener == NULL)
        return NULL;
    listener->done = callback;
    if (wl_proxy_add_listener((struct wl_proxy *) token,
                              (void (**)(void)) listener, data) < 0) {
        free(listener);
        return NULL;
    }
    return listener;
}

static inline void witty_wayland_listener_free(void *listener)
{
    free(listener);
}

static inline uint32_t witty_wayland_proxy_get_id(void *proxy)
{
    return wl_proxy_get_id((struct wl_proxy *) proxy);
}

static inline void witty_wayland_proxy_destroy(void *proxy)
{
    wl_proxy_destroy((struct wl_proxy *) proxy);
}

static inline void *witty_kde_decoration_create(void *manager, void *surface)
{
    return wl_proxy_marshal_flags((struct wl_proxy *) manager, 0,
        &witty_kde_decoration_interface,
        wl_proxy_get_version((struct wl_proxy *) manager), 0, NULL, surface);
}

static inline void witty_kde_decoration_request_mode(void *decoration,
                                                      uint32_t mode)
{
    wl_proxy_marshal_flags((struct wl_proxy *) decoration, 1, NULL,
        wl_proxy_get_version((struct wl_proxy *) decoration), 0, mode);
}

static inline void witty_kde_decoration_release(void *decoration)
{
    wl_proxy_marshal_flags((struct wl_proxy *) decoration, 0, NULL,
        wl_proxy_get_version((struct wl_proxy *) decoration),
        WL_MARSHAL_FLAG_DESTROY);
}

